class HomeView extends ConsumerStatefulWidget {
  const HomeView({super.key});

  static const routeName = "/home";

  @override
  ConsumerState<HomeView> createState() => _HomeViewState();
}

class _HomeViewState extends ConsumerState<HomeView>
    with WidgetsBindingObserver {
  final GlobalKey<ScaffoldState> _key = GlobalKey<ScaffoldState>();

  // keep reference to be able to remove listener in dispose without requiring the riverpod ref
  late final Prefs _prefs;

  late final RotateIconController _rotateIconController;

  late final List<Widget> _children;

  DateTime? _cachedTime;

  bool _exitEnabled = false;

  late TorConnectionStatus _currentSyncStatus;

  IdleMonitor? _idleMonitor;

  bool _lockOnResume = false;

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.paused && !goSessionLocked.value)
      _lockOnResume = true;
    if (state == AppLifecycleState.resumed && _lockOnResume) {
      _lockOnResume = false;
      _onIdle();
    }
  }

  void _onIdle() {
    if (!mounted) return;
    goSessionLocked.value = true;
  }

  late AutoLockInfo _autoLockInfo;
  void _prefsTimeoutListener() {
    final prefs = ref.read(prefsChangeNotifierProvider);
    if (mounted && prefs.autoLockInfo != _autoLockInfo) {
      _autoLockInfo = prefs.autoLockInfo;
      if (_autoLockInfo.enabled) {
        _idleMonitor?.detach();
        _idleMonitor = IdleMonitor(
          timeout: Duration(minutes: _autoLockInfo.minutes),
          onIdle: _onIdle,
        );
        _idleMonitor!.attach();
      } else {
        _idleMonitor?.detach();
        _idleMonitor = null;
      }
    }
  }

  // final _buyDataLoadingService = BuyDataLoadingService();

  Future<bool> _onWillPop() async {
    if (_key.currentState?.isDrawerOpen == true) {
      _key.currentState?.closeDrawer();
      return false;
    }
    // go to home view when tapping back on the main exchange view
    if (ref.read(homeViewPageIndexStateProvider.state).state != 0) {
      ref.read(homeViewPageIndexStateProvider.state).state = 0;
      return false;
    }

    if (_exitEnabled) {
      return true;
    }

    final now = DateTime.now();
    const timeout = Duration(milliseconds: 1500);
    if (_cachedTime == null || now.difference(_cachedTime!) > timeout) {
      _cachedTime = now;
      await showDialog<dynamic>(
        context: context,
        barrierDismissible: false,
        builder: (_) => WillPopScope(
          onWillPop: () async {
            _exitEnabled = true;
            return true;
          },
          child: StackDialog(title: goTr(context, "Tap back again to exit")),
        ),
      ).timeout(
        timeout,
        onTimeout: () {
          _exitEnabled = false;
          Navigator.of(context).pop();
        },
      );
    }
    return _exitEnabled;
  }

  // void _loadSimplexData() {
  //   // unawaited future
  //   if (ref.read(prefsChangeNotifierProvider).externalCalls) {
  //     _buyDataLoadingService.loadAll(ref);
  //   } else {
