  Future<void> precacheSettingsIcons(BuildContext context) async {
    if (Util.isDesktop) return;

    final icons = [
      Assets.svg.addressBook,
      Assets.svg.downloadFolder,
      Assets.svg.lock,
      Assets.svg.dollarSign,
      Assets.svg.language,
      Assets.svg.node,
      Assets.svg.arrowRotate,
      Assets.svg.arrowUpRight,
      Assets.svg.sun,
      Assets.svg.circleAlert,
      Assets.svg.ellipsis,
      Assets.svg.solidSliders,
      Assets.svg.questionMessage,
    ];

    for (final asset in icons) {
      final loader = SvgAssetLoader(asset);
      await svg.cache.putIfAbsent(
        loader.cacheKey(context),
        () => loader.loadBytes(context),
      );
    }
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();

    precacheSettingsIcons(context);
  }

  @override
  void initState() {
    WidgetsBinding.instance.addObserver(this);
    _prefs = ref.read(prefsChangeNotifierProvider);
    _autoLockInfo = ref.read(prefsChangeNotifierProvider).autoLockInfo;
    if (_autoLockInfo.enabled) {
      _idleMonitor = IdleMonitor(
        timeout: Duration(minutes: _autoLockInfo.minutes),
        onIdle: _onIdle,
      );
    }

    _rotateIconController = RotateIconController();
    _children = [
      const GoDashboard(),
      const GoNetworks(),
      const GoSecurity(),
      if (AppConfig.hasFeature(AppFeature.swap) && Constants.enableExchange)
        const ExchangeView(),
      if (AppConfig.hasFeature(AppFeature.buy) && Constants.enableExchange)
        const BuyView(),
    ];

    ref.read(notificationsProvider).startCheckingWatchedNotifications();

    // WidgetsBinding.instance.addPostFrameCallback((timeStamp) {
    //   showOneTimeTorHasBeenAddedDialogIfRequired(context);
    // });

    _idleMonitor?.attach();

    ref.read(prefsChangeNotifierProvider).addListener(_prefsTimeoutListener);

    super.initState();
  }

  @override
  dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _prefs.removeListener(_prefsTimeoutListener);
    _idleMonitor?.detach();
    _rotateIconController.forward = null;
    _rotateIconController.reverse = null;
    _rotateIconController.reset = null;
    super.dispose();
  }

  DateTime _hiddenTime = DateTime.now();
  int _hiddenCount = 0;

  void _hiddenOptions() {
    _rotateIconController.reset?.call();
    _rotateIconController.forward?.call();
    if (_hiddenCount == 5) {
      Navigator.of(context).pushNamed(HiddenSettings.routeName);
    }
    final now = DateTime.now();
    const timeout = Duration(seconds: 1);
    if (now.difference(_hiddenTime) < timeout) {
      _hiddenCount++;
    } else {
      _hiddenCount = 0;
    }
    _hiddenTime = now;
  }

