        if (next == false &&
            mounted &&
            ref.read(homeViewPageIndexStateProvider) != 0) {
          WidgetsBinding.instance.addPostFrameCallback(
            (_) => ref.read(homeViewPageIndexStateProvider.state).state = 0,
          );
        }
      },
    );

    return WillPopScope(
