              openWalletGroup(context, ref, holding.coin, holding.walletCount);
            },
            onAdd: (coin) {
              _key.currentState?.closeDrawer();
              goAddCoin(context, coin);
            },
          ),
          appBar: AppBar(
            automaticallyImplyLeading: false,
            backgroundColor: Theme.of(
              context,
            ).extension<StackColors>()!.backgroundAppBar,
            title: Row(
              children: [
                IconButton(
                  key: const Key('goCoinDrawerButton'),
                  tooltip: goTr(context, '打开币种导航'),
                  onPressed: () => _key.currentState?.openDrawer(),
                  icon: const GoMark(size: 34),
                ),
                const SizedBox(width: 12),
                Expanded(
                  child: Text(
                    goTr(context, "GOwallet"),
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: STextStyles.navBarTitle(
                      context,
                    ).copyWith(fontWeight: FontWeight.w800),
                  ),
                ),
              ],
            ),
            actions: [
              if (AppConfig.hasFeature(AppFeature.tor))
                const Padding(
                  padding: EdgeInsets.only(top: 10, bottom: 10, right: 10),
                  child: AspectRatio(aspectRatio: 1, child: SmallTorIcon()),
                ),
              Padding(
                padding: const EdgeInsets.only(top: 10, bottom: 10, right: 10),
                child: AspectRatio(
                  aspectRatio: 1,
                  child: AppBarIconButton(
                    semanticsLabel: goTr(
                      context,
                      "Notifications Button. Takes To Notifications Page.",
                    ),
                    key: const Key("walletsViewAlertsButton"),
                    size: 36,
                    shadows: const [],
                    color: Theme.of(
                      context,
                    ).extension<StackColors>()!.backgroundAppBar,
                    icon: Platform.isIOS
                        ? Icon(
                            ref.watch(
                                  notificationsProvider.select(
                                    (value) => value.hasUnreadNotifications,
                                  ),
                                )
                                ? CupertinoIcons.bell_fill
                                : CupertinoIcons.bell,
                            size: 20,
                            color: Theme.of(
                              context,
                            ).extension<StackColors>()!.topNavIconPrimary,
                          )
                        : ref.watch(
                            notificationsProvider.select(
                              (value) => value.hasUnreadNotifications,
                            ),
                          )
                        ? SvgPicture.file(
                            File(
                              ref.watch(
                                themeProvider.select(
                                  (value) => value.assets.bellNew,
                                ),
                              ),
                            ),
                            width: 20,
                            height: 20,
                            color:
                                ref.watch(
                                  notificationsProvider.select(
                                    (value) => value.hasUnreadNotifications,
                                  ),
                                )
                                ? null
                                : Theme.of(
                                    context,
                                  ).extension<StackColors>()!.topNavIconPrimary,
                          )
                        : SvgPicture.asset(
                            Assets.svg.bell,
                            width: 20,
                            height: 20,
                            color:
                                ref.watch(
                                  notificationsProvider.select(
                                    (value) => value.hasUnreadNotifications,
                                  ),
                                )
                                ? null
                                : Theme.of(
                                    context,
                                  ).extension<StackColors>()!.topNavIconPrimary,
                          ),
                    onPressed: () {
                      // reset unread state
                      ref.refresh(unreadNotificationsStateProvider);

                      Navigator.of(
                        context,
                      ).pushNamed(NotificationsView.routeName).then((_) {
                        final Set<int> unreadNotificationIds = ref
                            .read(unreadNotificationsStateProvider.state)
                            .state;
                        if (unreadNotificationIds.isEmpty) return;

                        final List<Future<void>> futures = [];
                        for (
                          int i = 0;
                          i < unreadNotificationIds.length - 1;
                          i++
                        ) {
                          futures.add(
                            ref
                                .read(notificationsProvider)
                                .markAsRead(
                                  unreadNotificationIds.elementAt(i),
                                  false,
                                ),
                          );
                        }

                        // wait for multiple to update if any
                        Future.wait(futures).then((_) {
                          // only notify listeners once
                          ref
                              .read(notificationsProvider)
                              .markAsRead(unreadNotificationIds.last, true);
                        });
                      });
                    },
                  ),
                ),
              ),
              Padding(
                padding: const EdgeInsets.only(top: 10, bottom: 10, right: 10),
                child: AspectRatio(
                  aspectRatio: 1,
                  child: AppBarIconButton(
                    semanticsLabel: goTr(
